package com.bank.upi.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

@Entity
@Table(name = "upi_transactions")
public class UpiTransaction {

    @Id
    @Column(name = "txn_id")
    private String txnId;

    @Column(name = "sender_vpa", nullable = false)
    private String senderVpa;

    @Column(name = "receiver_vpa", nullable = false)
    private String receiverVpa;

    @Column(nullable = false)
    private BigDecimal amount;

    private String note;

    @Column(nullable = false)
    private String status;

    @Column(name = "txn_date")
    private LocalDate txnDate;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected UpiTransaction() {}

    public UpiTransaction(String txnId, String senderVpa, String receiverVpa,
                           BigDecimal amount, String note) {
        this.txnId = txnId;
        this.senderVpa = senderVpa;
        this.receiverVpa = receiverVpa;
        this.amount = amount;
        this.note = note;
        this.status = "INITIATED";
        this.txnDate = LocalDate.now();
        this.createdAt = LocalDateTime.now();
    }

    public void succeed() { this.status = "SUCCESS"; }
    public void fail() { this.status = "FAILED"; }

    public String getTxnId() { return txnId; }
    public String getSenderVpa() { return senderVpa; }
    public String getReceiverVpa() { return receiverVpa; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
}
