package com.bank.upi.dto;

import jakarta.validation.constraints.*;
import java.math.BigDecimal;

public record UpiPaymentRequest(

    @NotBlank(message = "Sender VPA is required")
    @Pattern(regexp = "^[a-zA-Z0-9.]+@[a-zA-Z]+$", message = "Invalid VPA format (e.g. rajesh@upi)")
    String senderVpa,

    @NotBlank(message = "Receiver VPA is required")
    @Pattern(regexp = "^[a-zA-Z0-9.]+@[a-zA-Z]+$", message = "Invalid VPA format")
    String receiverVpa,

    @NotNull(message = "Amount is required")
    @DecimalMin(value = "1.00", message = "Minimum amount is Rs.1")
    @DecimalMax(value = "100000.00", message = "Maximum amount is Rs.1,00,000")
    BigDecimal amount,

    @Size(max = 200, message = "Note cannot exceed 200 characters")
    String note

) {}
