// SPRING JDBC (JdbcTemplate): for complex reporting queries that JPA cannot express cleanly
package com.bank.upi.service;

import com.bank.upi.dto.DailyReport;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.time.LocalDate;

@Service
@RequiredArgsConstructor
@Slf4j
public class TransactionReportService {

    private final JdbcTemplate jdbc;  // Spring JDBC — direct SQL, full control

    /**
     * Complex aggregation query — much cleaner with raw SQL than JPQL.
     * JPA would need @Query with constructor expression or a Specification.
     * JdbcTemplate gives full SQL control for reporting.
     */
    public DailyReport getDailyReport(LocalDate date) {
        log.info("Generating daily report for {}", date);

        return jdbc.queryForObject("""
            SELECT
                txn_date,
                COUNT(*) AS total_transactions,
                COALESCE(SUM(amount), 0) AS total_amount,
                COUNT(*) FILTER (WHERE status = 'SUCCESS') AS success_count,
                COUNT(*) FILTER (WHERE status = 'FAILED') AS failed_count
            FROM upi_transactions
            WHERE txn_date = ?
            GROUP BY txn_date
            """,
            (rs, rowNum) -> new DailyReport(
                rs.getDate("txn_date").toLocalDate(),
                rs.getLong("total_transactions"),
                rs.getBigDecimal("total_amount"),
                rs.getLong("success_count"),
                rs.getLong("failed_count")),
            date);
    }
}
