package com.bank.upi.controller;

import com.bank.upi.dto.*;
import com.bank.upi.service.*;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;

@RestController
@RequestMapping("/api/v1/upi")
@RequiredArgsConstructor
public class UpiController {

    private final UpiService upiService;
    private final TransactionReportService reportService;

    @PostMapping("/pay")
    @ResponseStatus(HttpStatus.CREATED)
    public UpiPaymentResponse pay(@RequestBody @Valid UpiPaymentRequest request) {
        // @Valid triggers Bean Validation on ALL annotated fields
        // If ANY fails: MethodArgumentNotValidException → GlobalExceptionHandler → 400
        return upiService.pay(request);
    }

    @GetMapping("/report/{date}")
    public DailyReport getDailyReport(
            @PathVariable @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date) {
        return reportService.getDailyReport(date);
    }
}
