package com.bank.upi.service;

import com.bank.upi.dto.*;
import com.bank.upi.model.UpiTransaction;
import com.bank.upi.repository.UpiTransactionRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class UpiServiceTest {

    @Mock UpiTransactionRepository txnRepo;
    @InjectMocks UpiService upiService;

    @Test
    void shouldProcessUpiPayment() {
        when(txnRepo.save(any(UpiTransaction.class))).thenAnswer(i -> i.getArgument(0));

        UpiPaymentResponse response = upiService.pay(
            new UpiPaymentRequest("rajesh@upi", "priya@upi", new BigDecimal("5000"), "Rent"));

        assertThat(response.status()).isEqualTo("SUCCESS");
        assertThat(response.senderVpa()).isEqualTo("rajesh@upi");
        verify(txnRepo).save(any(UpiTransaction.class));
    }

    @Test
    void shouldRejectSelfTransfer() {
        assertThatThrownBy(() -> upiService.pay(
            new UpiPaymentRequest("rajesh@upi", "rajesh@upi", new BigDecimal("100"), null)))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("Cannot send to yourself");
    }
}
